import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


def fund():
    """The fund's yearly returns, 1993 to 2024, in the order the file lists them."""
    return pd.Series({2022: -0.083, 2012: 0.103, 2013: 0.186, 2006: 0.112, 1997: 0.195, 2005: 0.168, 2016: 0.142, 2000: -0.081,
                      2015: 0.031, 1993: 0.204, 2003: 0.176, 2004: 0.094, 2001: -0.152, 1994: -0.058, 1995: 0.182, 2002: -0.243,
                      2018: -0.094, 1996: 0.121, 2014: 0.012, 2008: -0.312, 2024: 0.096, 1998: 0.108, 1999: 0.214, 2011: -0.052,
                      2009: 0.247, 2019: 0.163, 2007: 0.035, 2017: 0.118, 2023: 0.079, 2010: 0.118, 2020: -0.028, 2021: 0.171})


def short():
    """A second fund's yearly returns, 2016 to 2021, in no order."""
    return pd.Series({2019: 0.08, 2017: -0.12, 2018: 0.05, 2021: 0.6, 2016: -0.05, 2020: -0.3})


def _line(ax, name):
    """The line on ax whose label is name."""
    for ln in ax.get_lines():
        if ln.get_label() == name:
            return ln
    raise LookupError(f"no line labelled {name!r} on the Axes")
